-- Name: interview_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id uuid NOT NULL,
    sender text NOT NULL,
    message_type text NOT NULL,
    question_id text,
    content text NOT NULL,
    llm_model text,
    prompt_tokens integer,
    completion_tokens integer,
    total_tokens integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    cost_eur numeric(14,10),
    co2e_g numeric(14,8),
    water_l numeric(14,8),
    pricing_version text,
    CONSTRAINT interview_messages_completion_tokens_check CHECK (((completion_tokens IS NULL) OR (completion_tokens >= 0))),
    CONSTRAINT interview_messages_llm_usage_message_type_check CHECK ((((llm_model IS NULL) AND (prompt_tokens IS NULL) AND (completion_tokens IS NULL) AND (total_tokens IS NULL)) OR (message_type = ANY (ARRAY['feedback'::text, 'summary'::text])))),
    CONSTRAINT interview_messages_message_type_check CHECK ((message_type = ANY (ARRAY['question'::text, 'answer'::text, 'feedback'::text, 'summary'::text]))),
    CONSTRAINT interview_messages_prompt_tokens_check CHECK (((prompt_tokens IS NULL) OR (prompt_tokens >= 0))),
    CONSTRAINT interview_messages_sender_check CHECK ((sender = ANY (ARRAY['student'::text, 'ai'::text, 'system'::text]))),
    CONSTRAINT interview_messages_total_tokens_check CHECK (((total_tokens IS NULL) OR (total_tokens >= 0)))
);

