--
-- Name: org_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.org_settings (
    org_id uuid NOT NULL,
    short_name text,
    legal_name text,
    dpo_name text,
    dpo_email text,
    dpo_phone text,
    lawful_basis_students text,
    lawful_basis_staff text,
    retention_answers_value integer,
    retention_answers_unit text,
    retention_account_value integer,
    retention_account_unit text,
    retention_staff_value integer,
    retention_staff_unit text,
    supervisory_authority text,
    support_name text,
    support_email text,
    support_phone text,
    support_hours text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT org_settings_lawful_basis_staff_check CHECK (((lawful_basis_staff IS NULL) OR (lawful_basis_staff = ANY (ARRAY['public_task'::text, 'contract'::text])))),
    CONSTRAINT org_settings_lawful_basis_students_check CHECK (((lawful_basis_students IS NULL) OR (lawful_basis_students = ANY (ARRAY['public_task'::text, 'legal_obligation'::text, 'consent'::text])))),
    CONSTRAINT org_settings_retention_account_unit_check CHECK (((retention_account_unit IS NULL) OR (retention_account_unit = ANY (ARRAY['days'::text, 'months'::text, 'years'::text])))),
    CONSTRAINT org_settings_retention_account_value_check CHECK (((retention_account_value IS NULL) OR (retention_account_value > 0))),
    CONSTRAINT org_settings_retention_answers_unit_check CHECK (((retention_answers_unit IS NULL) OR (retention_answers_unit = ANY (ARRAY['days'::text, 'months'::text, 'years'::text])))),
    CONSTRAINT org_settings_retention_answers_value_check CHECK (((retention_answers_value IS NULL) OR (retention_answers_value > 0))),
    CONSTRAINT org_settings_retention_staff_unit_check CHECK (((retention_staff_unit IS NULL) OR (retention_staff_unit = ANY (ARRAY['days'::text, 'months'::text, 'years'::text])))),
    CONSTRAINT org_settings_retention_staff_value_check CHECK (((retention_staff_value IS NULL) OR (retention_staff_value > 0)))
);

