--
-- Name: TABLE transcription_calls; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.transcription_calls IS 'One row per speech-to-text call, including calls whose audio never became a submitted answer. Survives erasure of the student with its foreign keys nulled.';

--
-- Name: COLUMN transcription_calls.co2e_g; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transcription_calls.co2e_g IS 'NULL means Scaleway publishes no figure for this model. As of the 2026-09-03 catalog, whisper-large-v3 reports kg_co2_equivalent = 0 and omits water usage entirely, which is an absence of measurement rather than an absence of impact — do not sum these as though the zeros were measured.';

