--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    password_hash text NOT NULL,
    display_name text NOT NULL,
    role text NOT NULL,
    preferred_language text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    question_count integer,
    notice_version text,
    notice_language text,
    notice_ack_at timestamp with time zone,
    org_id uuid,
    status text DEFAULT 'active'::text NOT NULL,
    CONSTRAINT users_notice_language_check CHECK ((notice_language = ANY (ARRAY['sr'::text, 'en'::text, 'fr'::text, 'pt'::text]))),
    CONSTRAINT users_org_scope_chk CHECK ((((role = 'super_admin'::text) AND (org_id IS NULL)) OR ((role <> 'super_admin'::text) AND (org_id IS NOT NULL)))),
    CONSTRAINT users_preferred_language_check CHECK ((preferred_language = ANY (ARRAY['sr'::text, 'en'::text, 'fr'::text, 'pt'::text]))),
    CONSTRAINT users_question_count_check CHECK (((question_count IS NULL) OR ((question_count >= 1) AND (question_count <= 50)))),
    CONSTRAINT users_role_check CHECK ((role = ANY (ARRAY['student'::text, 'teacher'::text, 'admin'::text, 'super_admin'::text]))),
    CONSTRAINT users_status_check CHECK ((status = ANY (ARRAY['active'::text, 'suspended'::text])))
);

