-- Name: COLUMN users.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.status IS 'active | suspended. Suspension blocks sign-in and every authenticated request, and is reversible. It deletes nothing: see the erasure route for that.';

